"""Saved-only, source-bound residential driveway measurement and projection."""
from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path

from driveway_measurement import load_sources, measure


def _read(path):
    if not path.is_file():
        raise ValueError("Missing required source: " + str(path))
    return json.loads(path.read_text())


def _rows(path):
    if not path.is_file():
        raise ValueError("Missing required source: " + str(path))
    return [json.loads(line) for line in path.read_text().splitlines() if line.strip()]


def measure_context(values, geometry):
    return {"district": geometry["district"], "access": geometry["access"],
            "connected_roadway": geometry["road_connection"],
            "district_source": geometry["district_source"],
            "frontage_source": geometry["frontage_source"],
            "driveway_source": geometry["private_driveway_source"]}


def measure_sidewalk_stop(values, geometry):
    return {"first_sidewalk_frame": values["first_sidewalk_frame"],
            "last_pre_sidewalk_halt_frame": values["last_pre_sidewalk_halt_frame"],
            "pre_sidewalk_speed_mps": values["pre_sidewalk_speed_mps"],
            "statutory_immediately_prior_judgment": None}


def measure_pedestrian(values, geometry):
    return {"source_present": values["pedestrian_source_present"],
            "minimum_center_separation_m": values["minimum_pedestrian_center_separation_m"],
            "collision_avoidance_necessity_judgment": None}


def measure_roadway(values, geometry):
    return {"source_present": values["roadway_vehicle_source_present"],
            "first_roadway_frame": values["first_roadway_frame"],
            "minimum_center_separation_m": values["minimum_roadway_vehicle_center_separation_m"],
            "right_of_way_judgment": None}


def build(attempt):
    attempt = Path(attempt).resolve()
    config = _read(attempt / "config.json")
    case = config["case"]
    original = attempt / "original-attempt"
    for name in ("inventory.json", "frame_map.json", "driveway_geometry.json", "activity.json"):
        if not (original / name).is_file():
            raise ValueError("Missing required source: original-attempt/" + name)
    marker = attempt / "fixture-provenance.json"
    diagnostic = marker.is_file()
    if diagnostic:
        provenance = _read(marker)
        if (provenance.get("diagnostic_fixture") is not True or
                provenance.get("physical_acceptance_claimed") is not False):
            raise ValueError("untrusted synthetic driveway provenance")
    inventory, sources = load_sources(original, diagnostic=diagnostic)
    values = measure(original, case, diagnostic=diagnostic)
    frames = _rows(attempt / "video_frames.jsonl")
    trace = _rows(attempt / "trace.jsonl")
    original_frames = sources["frame_map"]["frames"]
    if (len(frames) != len(trace) or len(frames) != len(original_frames) or
            any(frames[i].get("video_frame") != i or
                frames[i].get("carla_frame") != row["frame"] or
                frames[i].get("time_s") != row["time_s"] or
                trace[i].get("frame") != row["frame"]
                for i, row in enumerate(original_frames))):
        raise ValueError("original driveway trace/video/frame join differs")
    geometry = sources["driveway_geometry"]
    paths = ("original-attempt/driveway_geometry.json", "original-attempt/activity.json")
    hashes = {name: hashlib.sha256((attempt / name).read_bytes()).hexdigest() for name in paths}
    methods = (("district_driveway_context", measure_context),
               ("sidewalk_stop_evidence", measure_sidewalk_stop),
               ("pedestrian_precedence_evidence", measure_pedestrian),
               ("roadway_approach_evidence", measure_roadway))
    report = {"format": "worker-analysis-report", "measurements": {
        key: {"value": function(values, geometry), "method": function.__name__,
              "sources": hashes} for key, function in methods},
        "analysis_complete": True, "legal_verdict_claimed": False,
        "limitations": ["Synthetic fixture is software evidence only." if diagnostic else
                        "Original Native evidence requires independent physical and pixel review.",
                        "No legal cutoff is inferred from measured speed, distance or frame order."]}
    return report, inventory, sources, values, frames, diagnostic


def save_result(attempt, report, inventory, sources, values, frames, diagnostic):
    from worker_exchange.native_output import validate_result
    config = _read(attempt / "config.json")
    construction = _read(attempt / "construction.json")
    channels = attempt / "channels"
    channels.mkdir(exist_ok=False)
    activities = sources["activity"]["samples"]
    geometry = sources["driveway_geometry"]
    provenance = {"source_kind": inventory["source_kind"],
                  "geometry_sha256": inventory["sources"]["driveway_geometry"]["sha256"],
                  "activity_sha256": inventory["sources"]["activity"]["sha256"]}
    evidence = []
    for channel in construction["recording_description"]["channels"]:
        name = channel["name"]
        path = channels / (name + ".jsonl")
        with path.open("x") as stream:
            for frame, activity in zip(frames, activities):
                if name == "driver_and_district_context":
                    value = {"ego_actor_id": geometry["ego_vehicle_id"],
                             "district": geometry["district"], "access": geometry["access"]}
                elif name == "driveway_sidewalk_roadway_geometry":
                    value = {"driveway_polygon_m": geometry["driveway_polygon_m"],
                             "sidewalk_polygon_m": geometry["sidewalk_polygon_m"],
                             "roadway_polygon_m": geometry["roadway_polygon_m"]}
                elif name == "ego_motion_and_body":
                    value = activity["ego"]
                elif name == "pedestrian_motion_and_body":
                    value = activity["pedestrian"] or {"present": False, "source": "original absence"}
                elif name == "approaching_vehicle_motion_and_body":
                    value = activity["roadway_vehicle"] or {"present": False, "source": "original absence"}
                elif name == "frame_map_and_cameras":
                    value = {"carla_frame": frame["carla_frame"], "video_frame": frame["video_frame"],
                             "camera_sources": sorted(inventory.get("media", {}))}
                else:
                    raise ValueError("unknown required driveway channel: " + name)
                stream.write(json.dumps({"time_s": frame["time_s"], "value": value}) + "\n")
        evidence.append({"name": name, "unit": channel["unit"],
                         "reference": str(path.relative_to(attempt))})
    context = channels / "context.json"
    context.write_text(json.dumps({"reviewed_residential_driveway_context": provenance}) + "\n")
    for row in construction["recording_description"]["context_inputs"]:
        evidence.append({"name": row["name"], "unit": row["unit"],
                         "reference": str(context.relative_to(attempt))})
    observation = sources["activity"].get("observation_status", "complete")
    if observation not in ("complete", "missing"):
        raise ValueError("unknown original activity observation status")
    if observation == "missing":
        statuses = {key: "unverified" for key in ("setup", "target", "maneuver")}
    else:
        statuses = {"setup": "met", "target": "met" if values["first_sidewalk_frame"] is not None else "not_met",
                    "maneuver": "met" if values["first_sidewalk_frame"] is not None and
                    values["first_roadway_frame"] is not None else "not_met"}
    physical_checks = {key: {
        "status": status,
        "method": "source-joined original driveway samples; physical review remains local",
        "sources": {"original-attempt/" + name + ".json": digest
                    for name, digest in values["source_sha256"].items()},
        "available_intervals": [[frames[0]["time_s"], frames[-1]["time_s"]]],
        "detail": {"first_sidewalk_frame": values["first_sidewalk_frame"],
                   "first_roadway_frame": values["first_roadway_frame"],
                   "not_a_legal_threshold": True}}
        for key, status in statuses.items()}
    result = {
        "case_id": config["selected_case_id"],
        "measured_values": {name: item["value"] for name, item in report["measurements"].items()},
        "target_checks": [{"target": "original residence driveway sidewalk-to-roadway sequence",
                           "requested": "source-bound original crossing",
                           "measured": values["first_roadway_frame"],
                           "method": "measure original frame-joined geometry and activity",
                           "tolerance": 0, "matched": statuses["maneuver"] == "met",
                           "physical_cause_confirmed": False,
                           "cause_evidence": values["source_sha256"]}],
        "setup_confirmed": statuses["setup"] == "met",
        "behavior_attempted": statuses["target"] == "met",
        "maneuver_completed": statuses["maneuver"] == "met",
        "termination_reason": "saved original driveway source measured; legal and physical review pending",
        "physical_failure_flags": [], "trace_reference": "trace.jsonl",
        "video_references": [name + ".mkv" for name in
                             ("overview", "approach", "reference_corner", "driver_reference")],
        "video_frame_map_reference": "video_frames.jsonl",
        "recording_description": construction["recording_description"],
        "recording_evidence": evidence,
        "realized_observables": {"roadway_entry_frame": {
            "unit": "original frame", "method": "source-joined driveway activity and roadway polygon",
            "time_window": "full original episode", "statistic": "first entry",
            "reference": "original-attempt/activity.json",
            "value": values["first_roadway_frame"]}}
        if statuses["maneuver"] == "met" else {},
        "physical_checks": physical_checks,
        "provenance_kind": "synthetic_fixture" if diagnostic else "native",
        "diagnostic_fixture": diagnostic,
        "physical_acceptance_claimed": False,
    }
    validate_result(result)
    return result


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--attempt", required=True, type=Path)
    parser.add_argument("--output", required=True, type=Path)
    args = parser.parse_args()
    attempt = args.attempt.resolve()
    report, inventory, sources, values, frames, diagnostic = build(attempt)
    result = save_result(attempt, report, inventory, sources, values, frames, diagnostic)
    report["physical_checks"] = result["physical_checks"]
    report["realized_observables"] = result["realized_observables"]
    if (attempt / "result.json").exists() or args.output.exists():
        raise ValueError("refusing to replace saved original analysis")
    (attempt / "result.json").write_text(json.dumps(result, indent=2) + "\n")
    args.output.write_text(json.dumps(report, indent=2) + "\n")


if __name__ == "__main__":
    main()

"""Survey and reconstruct the selected residential driveway geometry.

All coordinates are original-map metres. A reviewed packet must accompany the
local CARLA run; a string naming a driveway never substitutes for the surveyed
sidewalk and connected roadway. This module has no CARLA import.
"""
from __future__ import annotations

import math


def _xy(value, name):
    if (not isinstance(value, (list, tuple)) or len(value) != 2 or
            any(type(v) not in (int, float) or not math.isfinite(v) for v in value)):
        raise ValueError("invalid original coordinate: " + name)
    return float(value[0]), float(value[1])


def _polygon(value, name):
    if not isinstance(value, list) or len(value) < 3:
        raise ValueError("missing original polygon: " + name)
    poly = [_xy(v, name) for v in value]
    area = sum(poly[i][0] * poly[(i + 1) % len(poly)][1] -
               poly[(i + 1) % len(poly)][0] * poly[i][1]
               for i in range(len(poly))) / 2
    if abs(area) < 0.1:
        raise ValueError("degenerate original polygon: " + name)
    return poly


def _inside(point, polygon):
    x, y = point
    inside = False
    for i, (x1, y1) in enumerate(polygon):
        x2, y2 = polygon[(i + 1) % len(polygon)]
        if (y1 > y) != (y2 > y) and x < (x2 - x1) * (y - y1) / (y2 - y1) + x1:
            inside = not inside
    return inside


def survey(packet):
    """Demand an original ordered route and participant approaches.

    This validates geometric *possibility*. Actual wheel/body containment and
    clearance remain measured from the physical episode.
    """
    if packet.get("source_kind") != "original_native_geometry":
        raise ValueError("original native driveway geometry missing")
    required = ("map_sha256", "district_source", "frontage_source",
                "private_driveway_source", "sidewalk_source", "roadway_source",
                "connection_source", "ego_vehicle_id")
    for key in required:
        if not packet.get(key):
            raise ValueError("reviewed driveway source missing: " + key)
    if packet.get("district") != "residence" or packet.get("business_district") is not False:
        raise ValueError("selected residence district not source established")
    if packet.get("access") != "private_driveway" or packet.get("road_connection") is not True:
        raise ValueError("private driveway to roadway connection unverified")
    if packet.get("crosswalk_assumed") or packet.get("controlled_access_assumed"):
        raise ValueError("unsupported crosswalk or controlled-access premise")
    regions = {name: _polygon(packet.get(name + "_polygon_m"), name)
               for name in ("driveway", "sidewalk", "roadway")}
    route = [_xy(point, "ego_route") for point in packet.get("ego_route_xy_m", [])]
    if len(route) < 5:
        raise ValueError("ego route needs sampled private approach and roadway entry")
    states = []
    for point in route:
        membership = tuple(name for name, poly in regions.items() if _inside(point, poly))
        states.append(membership)
    first_driveway = next((i for i, state in enumerate(states) if "driveway" in state), None)
    first_sidewalk = next((i for i, state in enumerate(states) if "sidewalk" in state), None)
    first_roadway = next((i for i, state in enumerate(states) if "roadway" in state), None)
    if not all(i is not None for i in (first_driveway, first_sidewalk, first_roadway)):
        raise ValueError("route omits driveway, sidewalk or roadway")
    if not (first_driveway < first_sidewalk < first_roadway):
        raise ValueError("driveway-sidewalk-roadway route order invalid")
    if first_sidewalk < 1 or "sidewalk" in states[first_sidewalk - 1]:
        raise ValueError("no original pre-sidewalk stop location")
    if first_roadway < first_sidewalk + 1:
        raise ValueError("no sidewalk crossing before roadway entry")
    approaches = packet.get("roadway_approaches", {})
    if not isinstance(approaches, dict) or set(approaches) != {"left", "right"}:
        raise ValueError("both roadway approach directions required")
    for direction in ("left", "right"):
        row = approaches[direction]
        if not row.get("lane_source") or len(row.get("route_xy_m", [])) < 2:
            raise ValueError("sourced roadway route missing: " + direction)
        a, b = (_xy(v, direction) for v in row["route_xy_m"][:2])
        if math.dist(a, b) < 1:
            raise ValueError("roadway approach route degenerate: " + direction)
        if not any(_inside(_xy(v, direction), regions["roadway"])
                   for v in row["route_xy_m"]):
            raise ValueError("roadway participant not on roadway: " + direction)
    pedestrian = packet.get("pedestrian_route_xy_m", [])
    if len(pedestrian) < 2 or not any(_inside(_xy(v, "pedestrian"), regions["sidewalk"])
                                          for v in pedestrian):
        raise ValueError("pedestrian route does not cross sidewalk area")
    return {
        "ego_route_xy_m": [list(v) for v in route],
        "stop_point_xy_m": list(route[first_sidewalk - 1]),
        "sidewalk_entry_index": first_sidewalk,
        "roadway_entry_index": first_roadway,
        "roadway_approaches": approaches,
        "pedestrian_route_xy_m": pedestrian,
        "survey_states": [list(v) for v in states],
        "source_kind": "original_native_geometry",
    }


def construct(packet, case):
    plan = survey(packet)
    world = case["world_setup"]
    if world["district"] != "residence" or world["access"] != "private_driveway":
        raise ValueError("selected world facts differ")
    if world["roadway_vehicle"].startswith("left_"):
        direction = "left"
    elif world["roadway_vehicle"].startswith("right_"):
        direction = "right"
    else:
        direction = None
    plan.update({
        "case_id": case["case_id"],
        "ego_entry_behavior": case["controller"]["entry_behavior"],
        "pedestrian_mode": world["pedestrian"],
        "roadway_vehicle_mode": world["roadway_vehicle"],
        "active_roadway_direction": direction,
        "termination_rule": "after recorded road entry or end of 900 synchronized frames",
        "legal_judgment": "unresolved",
    })
    return plan

"""Low-level route follower with separately recorded stop and precedence requests.

The controller's requested phases are never used as proof of actual stopping,
pedestrian necessity or roadway right-of-way. Original kinematics determine those.
"""
from __future__ import annotations

import math


class DrivewayController:
    def __init__(self, plan, *, max_speed_mps=3.0):
        self.plan = plan
        self.route = [tuple(v) for v in plan["ego_route_xy_m"]]
        self.stop = tuple(plan["stop_point_xy_m"])
        self.max_speed = max_speed_mps
        self.phase = "approach"
        self.hold_ticks = 0
        self.next_waypoint = 1

    def step(self, xy_m, yaw_rad, speed_mps, pedestrian_clear, roadway_clear):
        x, y = xy_m
        if any(not math.isfinite(v) for v in (x, y, yaw_rad, speed_mps)):
            raise ValueError("original controller state invalid")
        if self.next_waypoint >= len(self.route):
            self.phase = "complete"
            return {"throttle": 0.0, "brake": 1.0, "steer": 0.0, "phase": self.phase}
        while self.next_waypoint < len(self.route) - 1 and math.dist(
                (x, y), self.route[self.next_waypoint]) < 1.0:
            self.next_waypoint += 1
        target = self.route[self.next_waypoint]
        heading = math.atan2(target[1] - y, target[0] - x)
        heading_error = (heading - yaw_rad + math.pi) % (2 * math.pi) - math.pi
        steer = max(-1.0, min(1.0, 1.2 * heading_error))
        stop_distance = math.dist((x, y), self.stop)
        stop_requested = self.plan["ego_entry_behavior"] != "roll_across_sidewalk"
        if self.phase == "approach" and stop_requested and stop_distance < 2.0:
            self.phase = "pre_sidewalk_stop"
        if self.phase == "pre_sidewalk_stop":
            if speed_mps < 0.08:
                self.hold_ticks += 1
            if self.hold_ticks >= 4:
                self.phase = "sidewalk_wait"
            else:
                return {"throttle": 0.0, "brake": 1.0, "steer": steer, "phase": self.phase}
        pedestrian_mode = self.plan["pedestrian_mode"]
        if (self.phase == "sidewalk_wait" and
                pedestrian_mode == "pedestrian_crossing_yield" and not pedestrian_clear):
            return {"throttle": 0.0, "brake": 1.0, "steer": steer, "phase": self.phase}
        if self.phase in ("sidewalk_wait", "pre_sidewalk_stop"):
            self.phase = "sidewalk_crossing"
        road_index = self.plan["roadway_entry_index"]
        if self.next_waypoint >= road_index - 1:
            mode = self.plan["roadway_vehicle_mode"]
            if mode.endswith("_yield") and not roadway_clear:
                self.phase = "roadway_wait"
                return {"throttle": 0.0, "brake": 1.0, "steer": steer, "phase": self.phase}
            self.phase = "roadway_entry"
        target_speed = min(self.max_speed, 1.8 if self.phase == "sidewalk_crossing" else 2.5)
        error = target_speed - speed_mps
        throttle = max(0.0, min(0.45, 0.22 * error))
        brake = max(0.0, min(0.8, -0.35 * error))
        return {"throttle": throttle, "brake": brake, "steer": steer, "phase": self.phase}

"""Lazy CARLA session for an operator-reviewed residential driveway packet.

The reviewed packet identifies original map geometry, district and access
sources, actor spawn transforms, participant routes and four camera poses.
No source claim here is a legal verdict or proof of physical visibility.
"""
from __future__ import annotations

import hashlib
import io
import json
import math
import threading
import time
from pathlib import Path

from driveway_construction import survey
from driveway_controller import DrivewayController

CAMERAS = (("overview", 1920, 1080), ("approach", 1280, 720),
           ("reference_corner", 1280, 720), ("driver_reference", 1280, 720))
SOURCE_FIELDS = ("district_source", "frontage_source", "private_driveway_source",
                 "sidewalk_source", "roadway_source", "connection_source")


def _source(value, label):
    if not isinstance(value, dict) or not value.get("path") or not value.get("sha256"):
        raise ValueError("reviewed source missing: " + label)
    path = Path(value["path"])
    if not path.is_file() or hashlib.sha256(path.read_bytes()).hexdigest() != value["sha256"]:
        raise ValueError("reviewed source hash changed: " + label)
    return path


def _triple(value, label):
    if (not isinstance(value, list) or len(value) != 3 or
            any(type(v) not in (int, float) or not math.isfinite(v) for v in value)):
        raise ValueError("reviewed CARLA pose missing: " + label)
    return tuple(float(v) for v in value)


def validate_packet(path, case_id):
    packet = json.loads(Path(path).read_text())
    if packet.get("case_id") != case_id or not packet.get("reviewer"):
        raise ValueError("reviewed exact driveway packet missing")
    _source(packet.get("opendrive_source"), "OpenDRIVE")
    geometry = packet.get("geometry", {})
    if not isinstance(geometry, dict):
        raise ValueError("reviewed driveway geometry missing")
    for key in SOURCE_FIELDS:
        _source(geometry.get(key), key)
    flat = dict(geometry)
    for key in SOURCE_FIELDS:
        flat[key] = geometry[key]["sha256"]
    flat.update(case_id=case_id, source_kind="original_native_geometry",
                map_sha256=packet["opendrive_source"]["sha256"])
    survey(flat)
    for kind in ("ego", "pedestrian", "roadway_vehicle"):
        actor = packet.get("actors", {}).get(kind)
        if not isinstance(actor, dict) or not actor.get("blueprint_id"):
            raise ValueError("reviewed actor missing: " + kind)
        _triple(actor.get("spawn_xyz_m"), kind + " spawn")
        _triple(actor.get("spawn_rpy_deg"), kind + " rotation")
    cameras = packet.get("cameras")
    if not isinstance(cameras, list) or len(cameras) != 4:
        raise ValueError("reviewed four-camera poses missing")
    for (name, width, height), camera in zip(CAMERAS, cameras):
        if (camera.get("name"), camera.get("width"), camera.get("height")) != (name, width, height):
            raise ValueError("reviewed camera profile differs")
        _source(camera.get("pose_source"), name + " pose")
        _triple(camera.get("location_xyz_m"), name + " camera")
        _triple(camera.get("rotation_rpy_deg"), name + " rotation")
        if type(camera.get("fov_deg")) not in (int, float) or not 1 <= camera["fov_deg"] <= 170:
            raise ValueError("reviewed camera FOV invalid")
    return packet, flat


def _transform(carla, xyz, rpy):
    x, y, z = _triple(xyz, "xyz")
    roll, pitch, yaw = _triple(rpy, "rpy")
    return carla.Transform(carla.Location(x=x, y=y, z=z),
                           carla.Rotation(roll=roll, pitch=pitch, yaw=yaw))


def _speed(actor):
    v = actor.get_velocity()
    return math.sqrt(v.x * v.x + v.y * v.y + v.z * v.z)


class CameraBuffer:
    def __init__(self):
        self.condition = threading.Condition()
        self.frames = {}
        self.errors = []

    def receive(self, name, width, height, image):
        try:
            if (image.width, image.height) != (width, height) or len(image.raw_data) != width * height * 4:
                raise ValueError("original camera shape differs")
            from PIL import Image
            rgb = Image.frombytes("RGBA", (width, height), bytes(image.raw_data), "raw", "BGRA").convert("RGB")
            stream = io.BytesIO()
            rgb.save(stream, format="PNG")
            with self.condition:
                key = name, image.frame
                if key in self.frames:
                    raise ValueError("duplicate original camera frame")
                self.frames[key] = stream.getvalue()
                self.condition.notify_all()
        except BaseException as error:
            with self.condition:
                self.errors.append(error)
                self.condition.notify_all()

    def read(self, name, frame, timeout=15):
        end = time.monotonic() + timeout
        with self.condition:
            while (name, frame) not in self.frames and not self.errors:
                remaining = end - time.monotonic()
                if remaining <= 0:
                    raise ValueError("original camera frame absent: " + name)
                self.condition.wait(remaining)
            if self.errors:
                raise ValueError("original camera callback failed: " + str(self.errors[0]))
            return self.frames.pop((name, frame))


class Session:
    native_attested = True

    def __init__(self, client, world, carla, packet, geometry, actors, sensors, prior):
        self.client, self.world, self.carla = client, world, carla
        self.packet, self.geometry, self.actors = packet, geometry, actors
        self.sensors, self.prior = sensors, prior
        self.buffer = CameraBuffer()
        self.controller = None
        self.last = None
        self.closed = False
        self.restored = False
        self.capture_complete = False
        self.pipeline_capture = None
        for name, sensor, width, height in sensors:
            sensor.listen(lambda image, n=name, w=width, h=height:
                          self.buffer.receive(n, w, h, image))

    def geometry_packet(self, case_id):
        if case_id != self.geometry["case_id"]:
            raise ValueError("exact original case differs")
        return self.geometry

    def opendrive_bytes(self):
        return self.world.get_map().to_opendrive().encode("utf-8")

    def start(self, plan):
        if plan["case_id"] != self.geometry["case_id"]:
            raise ValueError("exact controller plan differs")
        self.controller = DrivewayController(plan)
        self.plan = plan

    def _participant_control(self, actor, route, speed_mps):
        transform = actor.get_transform()
        x, y = transform.location.x, transform.location.y
        end = route[-1]
        target_yaw = math.atan2(end[1] - y, end[0] - x)
        if actor.type_id.startswith("walker."):
            direction = self.carla.Vector3D(x=math.cos(target_yaw), y=math.sin(target_yaw), z=0)
            actor.apply_control(self.carla.WalkerControl(direction=direction, speed=speed_mps))
        else:
            err = (target_yaw - math.radians(transform.rotation.yaw) + math.pi) % (2 * math.pi) - math.pi
            actor.apply_control(self.carla.VehicleControl(
                throttle=max(0.0, min(0.45, .25 * (speed_mps - _speed(actor)))),
                brake=max(0.0, min(.8, .3 * (_speed(actor) - speed_mps))),
                steer=max(-1.0, min(1.0, err))))

    def tick(self):
        if self.controller is None:
            raise ValueError("original controller has not started")
        ego = self.actors["ego"]
        transform = ego.get_transform()
        point = (transform.location.x, transform.location.y)
        ped = self.actors.get("pedestrian")
        road = self.actors.get("roadway_vehicle")
        # Controller guard distances are engineering settings only; the saved
        # audit uses observed participant bodies and does not equate them to law.
        ped_clear = ped is None or math.dist(point, (ped.get_location().x, ped.get_location().y)) > 5
        road_clear = road is None or math.dist(point, (road.get_location().x, road.get_location().y)) > 8
        control = self.controller.step(point, math.radians(transform.rotation.yaw),
                                       _speed(ego), ped_clear, road_clear)
        ego.apply_control(self.carla.VehicleControl(throttle=control["throttle"],
                                                     brake=control["brake"], steer=control["steer"]))
        if ped is not None:
            self._participant_control(ped, self.plan["pedestrian_route_xy_m"], 1.1)
        if road is not None:
            route = self.plan["roadway_approaches"][self.plan["active_roadway_direction"]]["route_xy_m"]
            self._participant_control(road, route, 3.0)
        frame = self.world.tick()
        snapshot = self.world.get_snapshot()
        if snapshot.frame != frame:
            raise ValueError("original Native tick/snapshot frame differs")
        self.last = int(frame), float(snapshot.timestamp.elapsed_seconds)
        return {"frame": self.last[0], "time_s": self.last[1]}

    def activity(self, frame):
        if self.last is None or self.last[0] != frame:
            raise ValueError("original activity frame differs")
        def packet(actor, source, **extra):
            t = actor.get_transform()
            return {"actor_id": str(actor.id), "xy_m": [float(t.location.x), float(t.location.y)],
                    "speed_mps": float(_speed(actor)), "source": source, **extra}
        row = {"frame": frame, "time_s": self.last[1],
               "ego": packet(self.actors["ego"], "original_native_vehicle_state")}
        ped = self.actors.get("pedestrian")
        road = self.actors.get("roadway_vehicle")
        row["pedestrian"] = packet(ped, "original_native_walker_state") if ped else None
        row["roadway_vehicle"] = (packet(road, "original_native_vehicle_state",
                                          approach_direction=self.plan["active_roadway_direction"])
                                   if road else None)
        return row

    def cameras(self, frame):
        if self.last is None or self.last[0] != frame:
            raise ValueError("original camera frame differs")
        return {name: {"frame": frame, "time_s": self.last[1],
                       "png": self.buffer.read(name, frame)} for name, _, _, _ in self.sensors}

    def brake(self):
        self.actors["ego"].apply_control(self.carla.VehicleControl(throttle=0, brake=1))

    def cleanup(self):
        if self.closed:
            return
        self.closed = True
        errors = []
        if self.pipeline_capture is not None:
            try:
                self.pipeline_capture.close(confirmed=self.capture_complete)
            except BaseException as error:
                errors.append(error)
        for _, sensor, _, _ in reversed(self.sensors):
            try:
                sensor.stop()
                sensor.destroy()
            except BaseException as error:
                errors.append(error)
        for actor in self.actors.values():
            try:
                actor.destroy()
            except BaseException as error:
                errors.append(error)
        try:
            self.world.apply_settings(self.prior)
            settings = self.world.get_settings()
            self.restored = (settings.synchronous_mode == self.prior.synchronous_mode and
                             settings.fixed_delta_seconds == self.prior.fixed_delta_seconds and
                             settings.no_rendering_mode == self.prior.no_rendering_mode)
            if not self.restored:
                errors.append(ValueError("original world restoration readback differs"))
        except BaseException as error:
            errors.append(error)
        if errors:
            raise RuntimeError("CARLA driveway cleanup failed: " + "; ".join(map(str, errors)))


def open_session(case, packet_path, host, port, spawn_offset_m=0):
    packet, geometry = validate_packet(packet_path, case["case_id"])
    if not 0 <= spawn_offset_m <= .75:
        raise ValueError("fallback ego spawn offset outside surveyed envelope")
    # CARLA is imported only for the GPU command. CPU proofs use fake sessions.
    import carla
    client = carla.Client(host, int(port))
    client.set_timeout(20)
    world = client.get_world()
    if hashlib.sha256(world.get_map().to_opendrive().encode()).hexdigest() != geometry["map_sha256"]:
        raise ValueError("live map differs from reviewed original OpenDRIVE")
    prior = world.get_settings()
    settings = world.get_settings()
    settings.synchronous_mode = True
    settings.fixed_delta_seconds = .05
    settings.no_rendering_mode = False
    world.apply_settings(settings)
    actors = {}
    sensors = []
    try:
        library = world.get_blueprint_library()
        for kind in ("ego", "pedestrian", "roadway_vehicle"):
            if kind == "pedestrian" and case["world_setup"]["pedestrian"] == "pedestrian_absent":
                continue
            if kind == "roadway_vehicle" and case["world_setup"]["roadway_vehicle"] == "roadway_clear":
                continue
            spec = packet["actors"][kind]
            blueprint = library.find(spec["blueprint_id"])
            spawn = list(spec["spawn_xyz_m"])
            if kind == "ego":
                spawn[2] += spawn_offset_m
            transform = _transform(carla, spawn, spec["spawn_rpy_deg"])
            actor = world.try_spawn_actor(blueprint, transform)
            if actor is None:
                raise ValueError("original actor spawn failed: " + kind)
            actors[kind] = actor
        geometry["ego_vehicle_id"] = str(actors["ego"].id)
        for camera in packet["cameras"]:
            blueprint = library.find("sensor.camera.rgb")
            for key, value in (("image_size_x", camera["width"]),
                               ("image_size_y", camera["height"]),
                               ("fov", camera["fov_deg"])):
                blueprint.set_attribute(key, str(value))
            sensor = world.spawn_actor(blueprint, _transform(carla, camera["location_xyz_m"],
                                                              camera["rotation_rpy_deg"]))
            sensors.append((camera["name"], sensor, camera["width"], camera["height"]))
        return Session(client, world, carla, packet, geometry, actors, sensors, prior)
    except BaseException:
        for _, sensor, _, _ in reversed(sensors):
            sensor.destroy()
        for actor in actors.values():
            actor.destroy()
        world.apply_settings(prior)
        raise

"""Independent fixed-condition and measured-difference driveway comparison."""
from __future__ import annotations

import argparse
import json
from pathlib import Path

from driveway_measurement import load_sources, measure


def audit(left_root, right_root, left, right, comparison, *, diagnostic=False):
    if comparison["case_ids"] != [left["case_id"], right["case_id"]]:
        raise ValueError("comparison exact cases differ")
    if not comparison.get("fixed_conditions") or not comparison.get("deliberate_differences"):
        raise ValueError("comparison isolation declaration missing")
    fixed = ("district", "access", "sidewalk", "roadway")
    if any(left["world_setup"][key] != right["world_setup"][key] for key in fixed):
        raise ValueError("comparison fixed district/geometry differs")
    label = comparison["comparison_id"]
    if label == "stop_before_sidewalk":
        allowed = {"entry_behavior", "stop_target"}
        varied = "stop_halt_frame"
    elif label == "pedestrian_precedence":
        allowed = {"pedestrian"}
        varied = "pedestrian_separation_m"
    elif label in ("left_roadway_precedence", "right_roadway_precedence"):
        allowed = {"roadway_vehicle"}
        varied = "roadway_vehicle_separation_m"
    else:
        raise ValueError("unknown exact comparison")
    for section in ("world_setup", "controller"):
        lhs = left[section]
        rhs = right[section]
        for key in set(lhs) | set(rhs):
            if key not in allowed and lhs.get(key) != rhs.get(key):
                raise ValueError("comparison undeclared difference: " + key)
    _, left_source = load_sources(left_root, diagnostic=diagnostic)
    _, right_source = load_sources(right_root, diagnostic=diagnostic)
    geometry_fields = ("map_sha256", "district", "business_district", "access",
                       "road_connection", "driveway_polygon_m", "sidewalk_polygon_m",
                       "roadway_polygon_m", "ego_route_xy_m", "pedestrian_route_xy_m",
                       "roadway_approaches", "district_source", "frontage_source",
                       "private_driveway_source", "sidewalk_source", "roadway_source",
                       "connection_source")
    lg = left_source["driveway_geometry"]
    rg = right_source["driveway_geometry"]
    for key in geometry_fields:
        if lg.get(key) != rg.get(key):
            raise ValueError("comparison original geometry/source differs: " + key)
    left_measure = measure(left_root, left, diagnostic=diagnostic)
    right_measure = measure(right_root, right, diagnostic=diagnostic)
    for measure_name in ("first_sidewalk_frame", "first_roadway_frame"):
        if measure_name not in left_measure or measure_name not in right_measure:
            raise ValueError("comparison original timing source missing")
    return {"format": "worker-driveway-comparison-audit",
            "comparison_id": label, "case_ids": comparison["case_ids"],
            "fixed_conditions_checked": fixed,
            "deliberate_difference_measurement": varied,
            "left": left_measure, "right": right_measure,
            "legal_verdict_claimed": False,
            "physical_comparison_complete": False}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--comparison", required=True)
    parser.add_argument("--left", required=True, type=Path)
    parser.add_argument("--right", required=True, type=Path)
    parser.add_argument("--diagnostic", action="store_true")
    args = parser.parse_args()
    plan = json.loads((Path(__file__).resolve().parent / "case-plan.json").read_text())
    rows = [c for c in plan["comparisons"] if c["comparison_id"] == args.comparison]
    if len(rows) != 1:
        raise ValueError("comparison not found")
    row = rows[0]
    by_id = {c["case_id"]: c for c in plan["cases"]}
    print(json.dumps(audit(args.left, args.right, by_id[row["case_ids"][0]],
                           by_id[row["case_ids"][1]], row, diagnostic=args.diagnostic), sort_keys=True))


if __name__ == "__main__":
    main()
